#include "module/sg90_servo.hpp"
namespace fw::module{fw::Result<void>Sg90Servo::initialize(){if(min_>=max_||min_<500||max_>2500)return fw::Result<void>::failure(fw::Error::InvalidArgument);auto r=pwm_.start();if(!r)return r;return setPulseWidthUs(static_cast<std::uint16_t>((min_+max_)/2U));}fw::Result<void>Sg90Servo::setAngle(std::uint16_t d){if(d>180U)return fw::Result<void>::failure(fw::Error::InvalidArgument);const auto pulse=static_cast<std::uint16_t>(min_+(static_cast<std::uint32_t>(max_-min_)*d)/180U);return setPulseWidthUs(pulse);}fw::Result<void>Sg90Servo::setPulseWidthUs(std::uint16_t p){if(p<min_||p>max_)return fw::Result<void>::failure(fw::Error::InvalidArgument);return pwm_.setPulseWidthUs(p);}}
